Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName System.Windows.Forms

# Base64 pre-compiled executable data
$exeBase64 = ""

# Design the GUI Window using WPF XAML
[xml]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="TIA Portal Release Archiver Installer" Height="480" Width="550" 
        WindowStartupLocation="CenterScreen" ResizeMode="NoResize" Background="#F8FAFC">
    <Grid Margin="25">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>
        
        <!-- Header -->
        <StackPanel Grid.Row="0" Margin="0,0,0,20">
            <TextBlock Text="TIA Portal V18 Release Archiver Setup" FontSize="20" FontWeight="Bold" Foreground="#1E3A8A"/>
            <TextBlock Text="Install and configure the automated tag-triggered archiver on this developer machine." FontSize="12" Foreground="#64748B" Margin="0,5,0,0"/>
            <Border BorderBrush="#E2E8F0" BorderThickness="0,0,0,1" Margin="0,15,0,0"/>
        </StackPanel>
        
        <!-- Scrollable settings form -->
        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
            <StackPanel Margin="0,0,10,0">
                <!-- Project Server URL -->
                <TextBlock Text="TIA Project Server URL:" FontWeight="SemiBold" Foreground="#334155" Margin="0,0,0,4"/>
                <TextBox Name="ServerUrl" Text="https://192.168.1.192:8735/" Padding="8" BorderBrush="#CBD5E1" Margin="0,0,0,12" FontSize="13"/>
                
                <!-- Server Credentials -->
                <Grid Margin="0,0,0,12">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="15"/>
                        <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Grid.Column="0">
                        <TextBlock Text="Server Username:" FontWeight="SemiBold" Foreground="#334155" Margin="0,0,0,4"/>
                        <TextBox Name="Username" Text="deepak" Padding="8" BorderBrush="#CBD5E1" FontSize="13"/>
                    </StackPanel>
                    <StackPanel Grid.Column="2">
                        <TextBlock Text="Server Password:" FontWeight="SemiBold" Foreground="#334155" Margin="0,0,0,4"/>
                        <PasswordBox Name="Password" Padding="8" BorderBrush="#CBD5E1" FontSize="13"/>
                    </StackPanel>
                </Grid>
                
                <!-- TIA Server Project Name -->
                <TextBlock Text="Server Project Name (e.g. AR_V0.0):" FontWeight="SemiBold" Foreground="#334155" Margin="0,4,0,4"/>
                <TextBox Name="ProjectName" Text="AR_V0.0" Padding="8" BorderBrush="#CBD5E1" Margin="0,0,0,12" FontSize="13"/>
                
                <!-- Target Local Archive Path -->
                <TextBlock Text="Target Local Releases Directory (where .zap18 files are saved):" FontWeight="SemiBold" Foreground="#334155" Margin="0,4,0,4"/>
                <Grid Margin="0,0,0,15">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="85"/>
                    </Grid.ColumnDefinitions>
                    <TextBox Grid.Column="0" Name="ReleasePath" Text="C:\Users\Lucifer\Documents\GitVault\Releases" Padding="8" BorderBrush="#CBD5E1" FontSize="13"/>
                    <Button Grid.Column="1" Name="BrowseBtn" Content="Browse..." Margin="8,0,0,0" Padding="10,0"/>
                </Grid>
            </StackPanel>
        </ScrollViewer>
        
        <!-- Footer / Action Area -->
        <Grid Grid.Row="2" Margin="0,15,0,0">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <TextBlock Name="StatusTxt" Text="Ready to deploy." VerticalAlignment="Center" Foreground="#64748B" FontSize="12" TextWrapping="Wrap"/>
            <Button Grid.Column="1" Name="InstallBtn" Content="Install &amp; Enable Hook" Padding="20,10" FontWeight="Bold" Background="#2563EB" Foreground="White" BorderThickness="0" Cursor="Hand" FontSize="13"/>
        </Grid>
    </Grid>
</Window>
"@

# Load the XML nodes into WPF objects
$reader = (New-Object System.Xml.XmlNodeReader $xaml)
$window = [Windows.Markup.XamlReader]::Load($reader)

# Map WPF controls to variables
$serverUrlBox = $window.FindName("ServerUrl")
$usernameBox = $window.FindName("Username")
$passwordBox = $window.FindName("Password")
$projectNameBox = $window.FindName("ProjectName")
$releasePathBox = $window.FindName("ReleasePath")
$browseBtn = $window.FindName("BrowseBtn")
$installBtn = $window.FindName("InstallBtn")
$statusTxt = $window.FindName("StatusTxt")

# Set dynamic defaults based on executing developer's environment
if ($usernameBox.Text -eq "deepak") {
    $usernameBox.Text = $env:USERNAME
}
if ($releasePathBox.Text -eq "C:\Users\Lucifer\Documents\GitVault\Releases") {
    $releasePathBox.Text = Join-Path $env:USERPROFILE "Documents\GitVault\Releases"
}

# Check if running as Administrator
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

# Event Handler: Browse Button click
$browseBtn.Add_Click({
    $dialog = New-Object System.Windows.Forms.FolderBrowserDialog
    $dialog.Description = "Select target release folder"
    $dialog.SelectedPath = $releasePathBox.Text
    if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $releasePathBox.Text = $dialog.SelectedPath
    }
})

# Event Handler: Install Button click
$installBtn.Add_Click({
    $installBtn.IsEnabled = $false
    $statusTxt.Text = "Installing files..."
    $statusTxt.Foreground = [Windows.Media.Brushes]::Blue
    
    # 1. Determine the installation path
    $installDir = "C:\Program Files\TiaReleaseArchiver"
    if (-not $isAdmin) {
        $installDir = Join-Path $env:LOCALAPPDATA "TiaReleaseArchiver"
    }
    
    try {
        # Create folder
        if (-not (Test-Path $installDir)) {
            New-Item -ItemType Directory -Force -Path $installDir | Out-Null
        }
        
        # 2. Extract Base64 binary to disk
        $exePath = Join-Path $installDir "TiaReleaseArchiver.exe"
        [IO.File]::WriteAllBytes($exePath, [Convert]::FromBase64String($exeBase64))
        
        # 3. Create app.config dynamic configuration XML
        $configPath = Join-Path $installDir "TiaReleaseArchiver.exe.config"
        $configContent = @"
<?xml version="1.0" encoding="utf-8" ?>
<configuration>
    <appSettings>
        <add key="ProjectServerName" value="ProjectServer" />
        <add key="ProjectServerUrl" value="$($serverUrlBox.Text)" />
        <add key="ServerProjectName" value="$($projectNameBox.Text)" />
        <add key="TempSessionPath" value="%TEMP%\Openness_Export" />
        <add key="TargetReleasePath" value="$($releasePathBox.Text)" />
        <add key="ServerUsername" value="$($usernameBox.Text)" />
        <add key="ServerPassword" value="$($passwordBox.Password)" />
        <add key="UmacUsername" value="" />
        <add key="UmacPassword" value="" />
        <add key="GitHubReleaseRepo" value="" />
    </appSettings>
    <startup>
        <supportedRuntime version="v4.0" sku=".NETFramework,Version=v4.8" />
    </startup>
    <runtime>
        <assemblyBinding xmlns="urn:schemas-microsoft-com:asm.v1">
            <dependentAssembly>
                <assemblyIdentity name="Siemens.Engineering" publicKeyToken="d29ec89bac048f84" culture="neutral" />
                <publisherPolicy apply="no" />
            </dependentAssembly>
            <dependentAssembly>
                <assemblyIdentity name="Siemens.Engineering.Hmi" publicKeyToken="d29ec89bac048f84" culture="neutral" />
                <publisherPolicy apply="no" />
            </dependentAssembly>
        </assemblyBinding>
    </runtime>
</configuration>
"@
        [IO.File]::WriteAllText($configPath, $configContent)
        
        # 4. Configure local Git hooks path if .git exists in the workspace
        if (Test-Path ".git") {
            & git config core.hooksPath hooks
            $statusTxt.Text = "Installed successfully! Git hook core.hooksPath registered."
            $statusTxt.Foreground = [Windows.Media.Brushes]::Green
            [System.Windows.MessageBox]::Show("TiaReleaseArchiver successfully installed at:`n$installDir`n`nGit hooks are configured in this repository.", "Installation Success", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Information)
        } else {
            $statusTxt.Text = "Archiver installed! Warning: Run from a Git workspace root to set hooks."
            $statusTxt.Foreground = [Windows.Media.Brushes]::Orange
            [System.Windows.MessageBox]::Show("TiaReleaseArchiver successfully installed at:`n$installDir`n`nWarning: No local .git folder detected. Please configure hooks manually or run this script from the root of your Git repository.", "Installation Warning", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning)
        }
        $window.Close()
    }
    catch {
        $statusTxt.Text = "Installation failed: $_"
        $statusTxt.Foreground = [Windows.Media.Brushes]::Red
        [System.Windows.MessageBox]::Show("An error occurred during installation:`n$_", "Installation Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
        $installBtn.IsEnabled = $true
    }
})

# Display Window
$window.ShowDialog() | Out-Null
